\begin{algorithm}[!h]
\caption{Quality-Aware Training Framework}
\label{alg:quality_aware_training}
\begin{algorithmic}[1]
\Require Training data $\mathcal{D}$, quality metadata $\mathcal{M} = \{\text{GFSC QC, S2 SCL, AOT/WVP}\}$, epochs $E$,
         $\tau_{init}{=}0.9$, $\tau_{final}{=}0.3$, $\lambda{=}3$, strength $\alpha$, source weights $\{\beta_j\}_{j=1}^{K}$
\Ensure  Trained model $\theta$ with calibrated uncertainty head
\State Initialize model parameters $\theta$
\For{$e = 1$ \textbf{to} $E$}
    \State $p \leftarrow e / E$ \Comment{training progress fraction}
    \State $\tau(e) \leftarrow \max\!\left(\tau_{init} \cdot \exp(-\lambda \cdot p),\; \tau_{final}\right)$ \Comment{curriculum threshold decay}
    \For{each mini-batch $\mathcal{B} = (x_{S1}, x_{S2}, y, \mathbf{q}) \sim \mathcal{D}$}
        \State $\mathcal{B}' \leftarrow \{i \in \mathcal{B} : q_i \geq \tau(e)\}$ \Comment{curriculum filtering}
        \State $(\hat{y}, \mathbf{z}) \leftarrow f_\theta(x_{S1}, x_{S2})$ \Comment{forward pass: prediction + raw uncertainty}
        \State $\sigma^2_i \leftarrow \log(1 + \exp(z_i))$ \Comment{softplus activation ensures $\sigma^2 > 0$}
        \State $w_i^{conf} \leftarrow \sigma(c_i)^{\alpha}$ \Comment{confidence weight from model predictions}
        \State $w_i^{qual} \leftarrow \prod_{j=1}^{K} q_{i,j}^{\beta_j}$ \Comment{multiplicative quality weight (QC, SCL, AOT/WVP)}
        \State $\mathcal{L}_{quality} \leftarrow \frac{1}{|\mathcal{B}'|}\sum_{i \in \mathcal{B}'} w_i^{conf} \cdot w_i^{qual} \cdot \mathcal{L}_{base}(y_i, \hat{y}_i)$
        \State $\mathcal{L}_{unc} \leftarrow -\frac{1}{|\mathcal{B}'|}\sum_{i \in \mathcal{B}'}\!\left[\tfrac{1}{2}\log(2\pi\sigma^2_i) + \tfrac{(y_i - \hat{y}_i)^2}{2\sigma^2_i}\right]$
        \State $\mathcal{L}_{total} \leftarrow \alpha\,\mathcal{L}_{reg} + \beta\,\mathcal{L}_{perc} + \gamma\,\mathcal{L}_{cons} + \delta\,\mathcal{L}_{unc}$
        \State $\theta \leftarrow \text{AdamW}(\theta,\; \nabla_\theta \mathcal{L}_{total})$
    \EndFor
\EndFor
\State \Return $\theta$ \Comment{ECE = 0.025; Moran's I = 0.548, $p = 0.002$}
\end{algorithmic}
\end{algorithm}

